package com.example.techfix.activities;
import android.content.*;import android.os.*;import android.text.TextUtils;import android.widget.EditText;import android.widget.RadioGroup;import android.widget.Toast;import androidx.appcompat.app.AppCompatActivity;import com.example.techfix.R;import com.example.techfix.database.DatabaseHelper;
public class ManageStaffActivity extends AppCompatActivity { private DatabaseHelper db; private EditText username,password; private RadioGroup roleGroup; public void onCreate(Bundle b){super.onCreate(b);String sessionRole=getSharedPreferences("TechFixPrefs",Context.MODE_PRIVATE).getString("userRole","");if(!"manager".equalsIgnoreCase(sessionRole)&&!"admin".equalsIgnoreCase(sessionRole)){Toast.makeText(this,"Access denied",Toast.LENGTH_SHORT).show();finish();return;}setContentView(R.layout.activity_manage_staff);db=new DatabaseHelper(this);username=findViewById(R.id.etManagerUsername);password=findViewById(R.id.etManagerPassword);roleGroup=findViewById(R.id.rgStaffRole);findViewById(R.id.btnCreateManager).setOnClickListener(v->create());findViewById(R.id.btnStaffBack).setOnClickListener(v->finish());}private void create(){String u=username.getText().toString().trim(),p=password.getText().toString();if(TextUtils.isEmpty(u)){username.setError("Enter a username or email");return;}if(p.length()<6){password.setError("Use at least 6 characters");return;}String role=roleGroup.getCheckedRadioButtonId()==R.id.rbStaff?"staff":"manager";new Thread(()->{boolean exists=db.isEmailExists(u);boolean ok=!exists&&db.createStaffAccount(u,p,role);runOnUiThread(()->{if(exists){username.setError("Username already exists");}else if(ok){Toast.makeText(this,("staff".equals(role)?"Staff":"Manager")+" account created",Toast.LENGTH_LONG).show();username.setText("");password.setText("");}else Toast.makeText(this,"Could not create account",Toast.LENGTH_LONG).show();});}).start();}protected void onDestroy(){if(db!=null)db.close();super.onDestroy();}}
